UPDATE scholarships SET title = 'Wellington Doctoral Scholarship', provider = 'Victoria University of Wellington (Te Herenga Waka)', coverage_type = 'Full Tuition + Stipend', amount_usd_value = 0, deadline = 'Three application rounds a year closing 1 March, 1 July and 1 November at 4.30pm (next: 1 November 2026); a completed online doctoral admission and scholarship application, including references, must be received by the closing date.', deadline_date = '2026-11-01', deadline_type = 'fixed', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["PhD"]$j$, eligible_majors = $j$["All"]$j$, eligible_countries = '[]', min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$The Wellington Doctoral Scholarship is Victoria University of Wellington's main PhD scholarship, offered to encourage and support doctoral study at Te Herenga Waka: around 110 scholarships are awarded each year on academic merit in three rounds closing on 1 March, 1 July and 1 November. Every offer consists of a NZ$32,000 per annum stipend (paid into the recipient's New Zealand bank account) plus domestic tuition fees (paid directly to the University's fees office), tenable for up to three years of full-time doctoral study; candidates who have already been enrolled in the doctorate for more than six months when an offer is made may receive a shorter tenure at the Research Scholarships Committee's discretion. The scholarships are offered to the top-ranked candidates in each doctoral admission and scholarship round, and offers are made about six weeks after each closing date. The scholarship cannot be deferred to a later year, and commencement is normally within six months of acceptance for domestic and nine months for international recipients.$desc$, requirements = $req$Open to graduates of any university within or outside New Zealand who intend to enrol full time for a PhD at Victoria University of Wellington, or who have commenced doctoral study there, and who are seeking their FIRST doctoral qualification (applicants who already hold a doctorate are ineligible). Applicants are normally expected to have completed a Bachelor's or Master's degree with academic distinction equivalent to a First Class Honours degree at a New Zealand university; to be considered they need a strong academic record with excellent academic references, demonstrated potential for high-quality research, or a record of publication in high-quality journals, with alignment to the host school's research also weighed. Applications are accepted from those eligible to register as a doctoral candidate at the time of application or who reasonably expect to become eligible within three months. That expected standard is a qualitative honours equivalence rather than a published numeric cutoff, so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://www.wgtn.ac.nz/scholarships/current/wellington-doctoral-scholarships', source_url = 'https://www.wgtn.ac.nz/scholarships/current/wellington-doctoral-scholarships', application_url = 'https://www.wgtn.ac.nz/scholarships/current/wellington-doctoral-scholarships', recurrence = 'annual', application_status = 'open', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-27 (cleanup pass 107) from Victoria University of Wellington's official Wellington Doctoral Scholarship page fetched the same day (value NZ$32,000 stipend per annum plus domestic tuition fees for up to three years; approximately 110 offered per year; rounds closing 1 March, 1 July and 1 November at 4.30pm with outcomes notified within about six to eight weeks; first-doctorate-only eligibility; First Class Honours-equivalent expectation; selection by the University Research Scholarships Committee on academic merit; commencement within six/nine months and no deferral). Title corrected to the scheme's official name; the previously stored website URL was the generic scholarships listing page. deadline_date 2026-11-01 is the next published round closing (this pass was verified five days before it) with status 'open' and the thrice-yearly pattern in rounds. university_id set to the existing Victoria University of Wellington record (253), previously NULL, and a university_scholarships row added. A separate 'Guaranteed Wellington Doctoral Scholarships' variant (GPA 8.5+ from a New Zealand university degree) exists on its own page and is deliberately not conflated with this open round. min_gpa/min_ielts NULL. Previous record held the scheme at reliability 4 with no values read. Source 2698 repointed from the bare domain to the fetched official scheme page.$note$, award_amount = 32000, award_currency = 'NZD', award_period = 'year', award_basis = 'fixed', living_allowance = NULL, funding_type = 'NZ$32,000 annual stipend + domestic tuition fees, normally for three years (approximately 110 scholarships per year)', tuition_coverage = 'Domestic tuition fees paid directly from the scholarship fund to the University fees office for up to three years of full-time doctoral enrolment.', english_requirements = 'The scholarship sets no IELTS cutoff; Victoria University of Wellington doctoral admission English-language requirements apply.', required_documents = $j$["Completed online doctoral admission and scholarship application by 4.30pm on the round closing date", "Supporting documentation including academic references (received by the closing date)", "Copy of academic record from prior institutions for applicants who have not completed all study at Victoria University of Wellington"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"cycle": "November 2026 round", "deadline": "2026-11-01", "status": "open"}, {"pattern": "Three rounds a year closing 1 March, 1 July and 1 November (4.30pm); offers made about six weeks after each closing date and outcomes notified by email within six to eight weeks"}]$json$ WHERE id = 381;

UPDATE scholarships SET university_id = 253, last_updated_at = now() WHERE id = 381;

UPDATE scholarships SET title = 'University of Otago Doctoral Scholarship', provider = 'University of Otago', coverage_type = 'Full Tuition + Stipend', amount_usd_value = 0, deadline = 'Apply at any time as part of the doctoral application via eVision; applications with a completed departmental assessment by the first day of a round month are considered at quarterly rounds held in March, June, September and November.', deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["PhD"]$j$, eligible_majors = $j$["All"]$j$, eligible_countries = '[]', min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$The University of Otago Doctoral Scholarship is Otago's main doctoral scholarship, providing funding to support doctoral students at the University of Otago: up to 153 scholarships are offered annually at a value of NZ$34,128 stipend per annum plus a domestic tuition fees waiver for 36 months of full-time doctoral enrolment (excluding the student services fee and insurance, which remain the student's). It is available to both domestic and international students, and candidates for professional doctorates (DClinDent, DMA, DBA, EdD) as well as the PhD are welcome - for professional doctorates the same NZ$34,128 stipend applies with the tuition fee waiver capped at the domestic rate for up to 36 months. Applicants can apply at any time through the doctoral application in eVision, with applications considered at quarterly rounds in March, June, September and November once the departmental assessment is complete (due by the first day of the round month). Selection is based predominantly on academic merit and the applicant's potential for research. Note that Otago's scholarships page currently carries an announcement that the University is reviewing its doctoral scholarship programme's strategic direction, so terms should be re-checked on the official page before applying.$desc$, requirements = $req$Open to domestic and international applicants for a PhD or professional doctorate at the University of Otago who are usually seeking to obtain their first doctoral qualification; selection is based predominantly on academic merit and research potential. The scholarship is applied for as part of the doctoral admission process via eVision, and a completed departmental assessment must be in place by the first day of the relevant quarterly round month for the application to be considered then. No numeric GPA or IELTS cutoff is published on the scholarship page, so min_gpa/min_ielts are not recorded.$req$, website_url = 'https://www.otago.ac.nz/courses/scholarships/university-of-otago-doctoral-scholarship', source_url = 'https://www.otago.ac.nz/courses/scholarships/university-of-otago-doctoral-scholarship', application_url = 'https://www.otago.ac.nz/courses/scholarships/university-of-otago-doctoral-scholarship', recurrence = 'annual', application_status = 'open', verification_status = 'verified', source_reliability = 9, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-27 (cleanup pass 107) from the University of Otago's official scholarships-database page fetched the same day (NZ$34,128 stipend per annum plus domestic tuition fees waiver for 36 months excluding student services fee and insurance; same package for the professional doctorates with the fee waiver capped at the domestic rate; up to 153 offered annually; apply anytime via eVision with a completed departmental assessment by the first day of each round month; quarterly rounds in March, June, September and November; first doctoral qualification; academic-merit selection). Reliability 9 (not 10): the official page banners that Otago is reviewing its doctoral scholarship programme, and Otago's June-2024 regulations document still circulates with the previous NZ$33,624 emolument - the fetched database page's NZ$34,128 is the currently published figure and is stored as a fixed annual award, with the review flagged in the description. deadline_date NULL/'not_published' (rolling applications with quarterly consideration rounds) and status 'open' because applications can be lodged at any time. Title corrected to the scheme's singular official name; the previously stored website URL was the generic scholarships listing. university_scholarships row 613 synced; source 2587 repointed from the bare domain to the fetched official database page; min_gpa/min_ielts NULL. Previous record held the scheme at reliability 4 with no values read.$note$, award_amount = 34128, award_currency = 'NZD', award_period = 'year', award_basis = 'fixed', living_allowance = NULL, funding_type = 'NZ$34,128 stipend per annum + domestic tuition fees waiver for 36 months (up to 153 scholarships annually)', tuition_coverage = 'Domestic tuition fees waived for 36 months of full-time doctoral enrolment (professional doctorates: waiver capped at the domestic rate); the student services fee and insurance are excluded.', english_requirements = 'The scholarship sets no IELTS cutoff; University of Otago doctoral admission English-language requirements apply.', required_documents = $j$["Doctoral admission and scholarship application via eVision", "Completed departmental assessment by the first day of the quarterly round month (March, June, September or November)"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"pattern": "Rolling: apply anytime via eVision; applications with a completed departmental assessment by the 1st of a round month are considered at quarterly rounds in March, June, September and November"}]$json$ WHERE id = 392;

UPDATE scholarships SET title = 'Massey University Doctoral Scholarship', provider = 'Massey University', coverage_type = 'Full Tuition + Stipend', amount_usd_value = 0, deadline = 'Annual round opening 1 August and closing 1 October (the 2026 round closed 1 October 2026); secure an admission offer of place for doctoral study before the scholarship closing date - allow at least four weeks for admission processing.', deadline_date = NULL, deadline_type = 'not_published', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["PhD"]$j$, eligible_majors = $j$["All"]$j$, eligible_countries = '[]', min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$Massey University Doctoral Scholarships are awarded to high-achieving students for doctoral study at Massey University - the Doctor of Philosophy (PhD), Doctor of Clinical Psychology (DClinPsych) or Doctor of Social Work (DSW) - in both full-time and part-time modes, with named scholarships also for Māori and Pacific doctoral candidates. The scholarship is worth NZ$90,000 plus fees over three years: a stipend (NZ$30,000 per annum) plus payment of tuition and non-tuition fees. Awards focus on the academic excellence of the student - expressly without limiting selection to GPA - together with the alignment of the research with the University, College and School research strategies, and successful applicants must be enrolled in their doctoral programme no later than 1 March of the year following the award. Applications run in an annual round opening 1 August and closing 1 October (the round verified for this record closed 1 October 2026).$desc$, requirements = $req$Applicants should be enrolled within the first 12 months of a doctoral degree at Massey University or hold an admission offer of place for doctoral study (conditional or unconditional) secured before the scholarship closing date; have a GPA of 7.0 or higher (on Massey's nine-point scale); be researching a topic of strategic value to the University; and agree to the scholarship conditions in the regulations. Selection considers academic achievements alongside strategic alignment with the University, College and supervisors' priorities. The GPA condition is expressed on Massey's nine-point scale rather than a 4.0 scale, so it is recorded here and min_gpa is not stored; no IELTS figure is published for the scholarship itself, so min_ielts is also NULL.$req$, website_url = 'https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-doctoral-scholarship/', source_url = 'https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-doctoral-scholarship/', application_url = 'https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-doctoral-scholarship/', recurrence = 'annual', application_status = 'upcoming', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-27 (cleanup pass 107) from Massey University's official Massey University Doctoral Scholarship page fetched the same day (value NZ$90,000 plus fees over three years; PhD/DClinPsych/DSW, full-time and part-time; 2026 round open 1 August and closed 1 October 2026; eligibility - enrolled within the first 12 months of doctoral study or holding an offer of place, GPA of 7.0 or higher, strategically valuable topic, enrolment by 1 March following the award; application checklist with a 200-1000-word research outline and the Supervisor Support Template; selection on excellence beyond GPA alone and strategic alignment). award stored as NZ$30,000/year (fixed), the annual rate of the official NZ$90,000-over-three-years stipend, with fees on top; older web pages quoting NZ$25,000 per annum date from superseded 2019 regulations and were not used. Title corrected to the scheme's official name; the previously stored URL (massey-doctoral-scholarship slug) returns 404. deadline_date NULL/'not_published' with the annual August-October pattern in rounds; status 'upcoming' because the verified round has closed. university_id set to the existing Massey University record (251), previously NULL, and a university_scholarships row added. min_gpa/min_ielts NULL (nine-point GPA scale; no IELTS figure). Previous record held the scheme at reliability 4 with no values read. Source 2571 repointed from the bare domain to the fetched official scheme page.$note$, award_amount = 30000, award_currency = 'NZD', award_period = 'year', award_basis = 'fixed', living_allowance = NULL, funding_type = 'NZ$90,000 stipend over three years (NZ$30,000 per annum) plus tuition and non-tuition fees (multiple awards)', tuition_coverage = 'Tuition and non-tuition fees are paid for the duration of the scholarship (three years full-time; part-time tenure applies per the scholarship regulations).', english_requirements = 'The scholarship sets no IELTS cutoff; Massey University doctoral admission English-language requirements apply.', required_documents = $j$["Admission offer of place for doctoral study at Massey University (conditional or unconditional) secured before the closing date, or enrolment within the first 12 months of the doctorate", "Research outline of 200-1000 words covering disciplinary area, aims and significance, and theoretical/methodological frameworks", "Completed Supervisor Support Template uploaded via the Student Portal"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"cycle": "2026 round", "deadline": "2026-10-01", "status": "closed"}, {"pattern": "Annual round: applications open 1 August and close 1 October; successful applicants enrol by 1 March of the following year"}]$json$, university_id = 251 WHERE id = 436;

UPDATE scholarships SET title = 'UC Doctoral Scholarship', provider = 'University of Canterbury', coverage_type = 'Full Tuition + Stipend', amount_usd_value = 0, deadline = 'Two application rounds a year closing 15 May and 15 October (11:59pm NZT); applications open 20 March for May and 20 August for October, and the doctoral admission application must also be submitted (via myUC) before the closing date. The 15 October 2026 round (for a start before 1 July 2027) has closed; the next round closes 15 May 2027.', deadline_date = '2027-05-15', deadline_type = 'fixed', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["PhD"]$j$, eligible_majors = $j$["All"]$j$, eligible_countries = '[]', min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$The UC Doctoral Scholarship is the core doctoral scholarship of Te Whare Wānanga o Waitaha | University of Canterbury, supporting students studying towards a research doctoral degree in any discipline in two application rounds a year (closing 15 May and 15 October). UC advertises the value as financial assistance of NZ$32,650 per 120 points of thesis enrolment plus tuition fees for thesis-only enrolment, for up to 360 points - 120 points being a year of full-time study, so the stipend equates to NZ$32,650 per annum for three years, with tuition fees covered at the New Zealand domestic rate under the regulations (the exact value is stated in each offer of award, and part-time awards are proportionate to the workload). Applying on this single core form files a candidate automatically for the aligned named doctoral scholarships - for example the UC Matariki Doctoral Scholarship for Māori candidates, the UC Pacific Doctoral Scholarship, the UC Connect and UC Commitments Doctoral Scholarships co-funded with external partners (canterbury's published at the same NZ$32,650 level), and the prestige top-ups awarded at the end of the academic year, which can raise the stipend from NZ$32,650 to NZ$37,650 per annum. The scholarships are tenable full time or part time, the number available is determined annually, and stipends are paid monthly into a New Zealand bank account.$desc$, requirements = $req$Per the official regulations: intending students who already hold a doctoral degree are not eligible; applicants must have submitted an application for admission to a research doctoral degree at the University of Canterbury before the scholarship closing date; candidates must have completed (or be completing) an appropriate qualifying degree or qualifications judged equivalent to a bachelor's degree with first-class honours or a master's with distinction, with the GPA of the last two years of relevant study equivalent to a UC GPA of at least 7.0 (UC's nine-point scale); and applicants may not have commenced doctoral studies at UC more than one year before the closing date. Selection considers academic achievement, research capability, project quality, fit with institutional strategic priorities, and the department's recommendation. There is no nationality restriction - eligibility is tied to the doctoral programme. The 7.0 figure is a UC nine-point-scale GPA, so it is recorded here and min_gpa is not stored; the scholarship publishes no IELTS figure, so min_ielts is also NULL.$req$, website_url = 'https://www.canterbury.ac.nz/study/getting-started/scholarships/doctoral-scholarships/uc-doctoral-scholarships', source_url = 'https://www.canterbury.ac.nz/study/getting-started/scholarships/doctoral-scholarships/uc-doctoral-scholarships', application_url = 'https://www.canterbury.ac.nz/study/getting-started/scholarships/doctoral-scholarships/uc-doctoral-scholarships', recurrence = 'annual', application_status = 'upcoming', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-27 (cleanup pass 107) from the University of Canterbury's official UC Doctoral Scholarships page and the UC Doctoral Scholarship regulations, both fetched the same day (listing value NZ$32,650 per 120 points plus tuition fees for thesis-only enrolment up to 360 points; 120 points equals a full-time year; regulations: value stated in the offer, tuition at the domestic rate, two rounds closing 15 May and 15 October, admission application required before the closing date, qualifying-degree + UC GPA 7.0 floor, no-doctorate rule, programme-based eligibility with no nationality restriction). Award stored as NZ$32,650/year with basis 'variable' because the regulations formally leave the value to the offer of award; the commonly published figure is the headline value on UC's own pages. deadline_date 2027-05-15 is the next published round closing (verified 2026-10-27, after the 15 October 2026 round closed); status 'upcoming' because applications for it open 20 March 2027. Title corrected to the official 'UC Doctoral Scholarship' (the regulations' name for the core award); the previously stored URL (doctoral-scholarship-programme slug) returns 404. university_id set to the existing University of Canterbury record (261), previously NULL, and a university_scholarships row added. min_gpa/min_ielts NULL (UC nine-point GPA scale; no IELTS figure). Previous record held the scheme at reliability 4 with no values read. Source 2498 repointed from the bare domain to the fetched official scheme page.$note$, award_amount = 32650, award_currency = 'NZD', award_period = 'year', award_basis = 'variable', living_allowance = NULL, funding_type = 'NZ$32,650 stipend per 120 points (one full-time year) + tuition fees for thesis-only enrolment, up to 360 points (exact value stated in each offer of award)', tuition_coverage = 'Tuition fees for thesis-only enrolment covered up to 360 points, charged at the Aotearoa New Zealand domestic rate under the regulations (paid directly to the recipient''s fees account).', english_requirements = 'The scholarship sets no IELTS cutoff; University of Canterbury research-doctoral admission English-language requirements apply.', required_documents = $j$["Online UC Doctoral Scholarship application by 11:59pm NZT on the closing date (15 May or 15 October)", "Application for admission to a research doctoral degree submitted via myUC before the closing date", "Evidence of the qualifying degree with GPA equivalent to at least UC GPA 7.0 over the last two years of relevant study"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"cycle": "October 2026 round (start before 1 July 2027)", "deadline": "2026-10-15", "status": "closed"}, {"cycle": "May 2027 round", "deadline": "2027-05-15", "status": "upcoming"}, {"pattern": "Two rounds a year: applications open 20 March and close 15 May, and open 20 August and close 15 October (11:59pm NZT)"}]$json$, university_id = 261 WHERE id = 435;

UPDATE scholarships SET title = 'University of Waikato Doctoral Scholarship', provider = 'University of Waikato', coverage_type = 'Full Tuition + Stipend', amount_usd_value = 0, deadline = 'Four rounds each year with closing dates of 31 January, 30 April, 31 July and 31 October (next: 31 October 2026); an Offer of Place into the doctoral programme is required before applying, and outcomes are advised up to eight weeks after the closing date.', deadline_date = '2026-10-31', deadline_type = 'fixed', deadline_range_start = NULL, deadline_range_end = NULL, degree_levels = $j$["PhD"]$j$, eligible_majors = $j$["All"]$j$, eligible_countries = '[]', min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $desc$The University of Waikato Doctoral Scholarship (established 1996) supports excellence in postgraduate research at the University of Waikato, for high-achieving candidates holding an Offer of Place in an approved higher research degree - the PhD, Doctor of Health Science, Doctor of Musical Arts or Doctor of Juridical Science. The standard scholarship pays a living allowance of NZ$33,000 every 12 months (in monthly instalments) for up to 36 months of full-time enrolment, plus the domestic tuition fees and the Student Services Fee for the tenure; part-time recipients are paid pro-rata, and a fees-only scholarship may be offered where appropriate. Applications are considered in four rounds each year (closing 31 January, 30 April, 31 July and 31 October, panels meeting in early March, June, September and December) as part of the University of Waikato Doctoral Scholarships Suite - the annual number of awards depends on the funding pool and applications are not considered outside the rounds. It is explicitly open to international students alongside New Zealand citizens/residents and Australians domiciled in New Zealand. Successful recipients must accept within 28 days, and the scholarship is backdated to the enrolment start for candidates who lawfully commenced study while their application was pending.$desc$, requirements = $req$Candidates must: be a New Zealand citizen, permanent resident or residence-class visa holder, an Australian citizen/permanent resident domiciled in New Zealand, OR an international student; have submitted a complete Application to Enrol AND received an Offer of Place into a Waikato doctoral qualification (PhD, DHSc, DMA or SJD) without yet having commenced enrolment at the round's closing date; normally intend full-time study; and not be employed by the University of Waikato (fixed-term sessional work may be permitted). Candidates who already hold a doctoral qualification, lack an Offer of Place by the closing date, or have already been considered twice for the scholarship are ineligible (students may apply at most twice). Selection is based on academic merit - a minimum GPA of A- on the qualification used for entry is required - plus research experience and readiness for independent research, supervisory capacity, alignment with university research priorities, knowledge of Mātauranga Māori and Pacific knowledges, and potential for impact. The A- minimum is a New Zealand letter-grade average, so it is recorded here and min_gpa is not stored; the scholarship publishes no IELTS figure, so min_ielts is also NULL.$req$, website_url = 'https://www.waikato.ac.nz/study/scholarships/find-a-scholarship/university-of-waikato-doctoral-scholarship/', source_url = 'https://www.waikato.ac.nz/study/scholarships/find-a-scholarship/university-of-waikato-doctoral-scholarship/', application_url = 'https://www.waikato.ac.nz/study/scholarships/find-a-scholarship/university-of-waikato-doctoral-scholarship/', recurrence = 'annual', application_status = 'open', verification_status = 'verified', source_reliability = 10, is_active = true, last_verified_at = now(), last_updated_at = now(), notes = $note$REWRITTEN 2026-10-27 (cleanup pass 107) from the University of Waikato Doctoral Scholarship 2026 regulations (version 3) and the live scholarship finder page, both fetched the same day (finder: 'up to NZ$33,000 per year plus domestic tuition fees and Student Services Fee, up to 36 months', status 'Accepting applications'; regulations clause 5.1: standard value is a living allowance of NZ$33,000 in total every 12 months in monthly instalments plus domestic tuition fees and the Student Services Fee, pro-rata for part-time; closing dates 31 January, 30 April, 31 July and 31 October; international students expressly eligible; Offer of Place required; A- GPA minimum on the entry qualification; at-most-two-applications rule; 28-day acceptance and outcome within eight weeks). Award stored as a fixed NZ$33,000/year because the regulations state the standard stipend as a flat amount; the finder's 'up to' reflects the 36-month cap and the fees-only variant, both noted in the description. deadline_date 2026-10-31 is the next published closing and the finder showed the scheme accepting applications at verification, so status is 'open'. The previously stored waikato.ac.nz URL redirected to the finder's generic listing. university_id set to the existing University of Waikato record (247), previously NULL, and a university_scholarships row added. min_gpa/min_ielts NULL (NZ letter-grade GPA; no IELTS figure). Previous record held the scheme at reliability 4 with no values read. Source 2695 repointed from the bare domain to the fetched official finder page.$note$, award_amount = 33000, award_currency = 'NZD', award_period = 'year', award_basis = 'fixed', living_allowance = NULL, funding_type = 'NZ$33,000 living allowance every 12 months (monthly instalments) for up to 36 months + domestic tuition fees + Student Services Fee', tuition_coverage = 'Domestic tuition fees for the doctoral qualification plus the Student Services Fee are covered for the tenure (a fees-only variant may be offered); medical insurance, moving costs and research expenses are not covered.', english_requirements = 'The scholarship sets no IELTS cutoff; University of Waikato doctoral admission English-language requirements apply.', required_documents = $j$["Offer of Place into a Waikato doctoral qualification (PhD, DHSc, DMA or SJD) following a complete Application to Enrol", "Online application to the University of Waikato Doctoral Scholarships Suite: confirmed thesis title and Chief Supervisor, and statements on research readiness, contribution/impact, Mātauranga Māori/Pacific connections and career aspirations", "Updated academic transcript where details changed since the enrolment application; one mandatory academic reference (and one optional professional reference)"]$j$, expected_opening_period = NULL, expected_deadline_period = NULL, rounds = $json$[{"cycle": "October 2026 round", "deadline": "2026-10-31", "status": "open"}, {"pattern": "Four rounds a year closing 31 January, 30 April, 31 July and 31 October; selection panels meet in early March, June, September and December and outcomes are advised up to eight weeks after closing (accept within 28 days)"}]$json$, university_id = 247 WHERE id = 437;

UPDATE sources SET url = CASE id WHEN 2698 THEN 'https://www.wgtn.ac.nz/scholarships/current/wellington-doctoral-scholarships' WHEN 2587 THEN 'https://www.otago.ac.nz/courses/scholarships/university-of-otago-doctoral-scholarship' WHEN 2498 THEN 'https://www.canterbury.ac.nz/study/getting-started/scholarships/doctoral-scholarships/uc-doctoral-scholarships' WHEN 2571 THEN 'https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-doctoral-scholarship/' WHEN 2695 THEN 'https://www.waikato.ac.nz/study/scholarships/find-a-scholarship/university-of-waikato-doctoral-scholarship/' ELSE url END, title = CASE id WHEN 2698 THEN 'Wellington Doctoral Scholarship - Victoria University of Wellington (official)' WHEN 2587 THEN 'University of Otago Doctoral Scholarship - Otago scholarships database (official)' WHEN 2498 THEN 'UC Doctoral Scholarships - University of Canterbury (official)' WHEN 2571 THEN 'Massey University Doctoral Scholarship (official)' WHEN 2695 THEN 'University of Waikato Doctoral Scholarship - finder (official)' ELSE title END, domain = CASE id WHEN 2698 THEN 'wgtn.ac.nz' WHEN 2587 THEN 'otago.ac.nz' WHEN 2498 THEN 'canterbury.ac.nz' WHEN 2571 THEN 'massey.ac.nz' WHEN 2695 THEN 'waikato.ac.nz' ELSE domain END, source_type = 'official_page', accessed_at = now(), is_official = true, is_verified = true WHERE id IN (2498, 2571, 2587, 2695, 2698);

